// A desktop from 2000 around the scene it wraps: the scene in a window with a
// yellow tab, the Deskbar in the top right corner and a few icons under it. The
// Deskbar's gem opens the scene list, its tray (signal, battery, clock) the frame's
// page, and below them the running scene puts its window away and brings it back,
// and Settings opens its settings. The tab's close box closes the scene to the
// list, its zoom box fills the desktop with the window and back, and a double tap
// on the tab hides the window. On a narrow panel the Deskbar runs along the top,
// with no room for the icons. Built-in scenes are drawn in the window too.
const pad = (n) => String(n).padStart(2, '0')
const on = (value) => value === true || value === 'true'

// Sizes are pixels, of a desktop's size, twice that on a panel with a short side
// of 1000 px or more, whose pixels are small, and in proportion on one under 480,
// which has no room for them. The frame's render scale multiplies on top.
let zoom = 1
let edge = 1 // the bevels' width
const px = (n) => `${Math.round(n * zoom * 10) / 10}px`

function clock(now, twentyFour) {
  const minutes = pad(now.getMinutes())
  if (twentyFour) return `${pad(now.getHours())}:${minutes}`
  return `${now.getHours() % 12 || 12}:${minutes} ${now.getHours() < 12 ? 'AM' : 'PM'}`
}

// The colors of the time. On e-paper the light grey is white, as a dithered grey
// is a field of dots there, and the bevels' shade is black.
const R5 = {
  desk: 'bg-[#336698]',
  panel: '#d8d8d8',
  pressed: '#b8b8b8',
  light: '#ffffff',
  shade: '#989898',
  line: '#6c6c6c',
  tab: '#ffcb00',
  tabLight: '#fff0a0',
  tabShade: '#c49600',
}
const PAPER = { ...R5, panel: '#ffffff', pressed: '#ffffff', shade: '#000000', line: '#000000', tabShade: '#000000' }
const MONO = { ...R5, desk: 'bg-[#4a4a4a]', line: '#000000', shade: '#7a7a7a' }
let c = R5

// A box has one border color, so a bevel is two boxes inside each other: light
// at the top and the left, shade at the bottom and the right. Pressed, they swap.
const Bevel = ({ pressed = false, className = '', inner = '', onClick, children }) => (
  <div
    className={`flex border-t-${edge} border-l-${edge} border-[${pressed ? c.shade : c.light}] ${className}`}
    onClick={onClick}
  >
    <div
      className={`flex flex-1 min-w-0 min-h-0 border-b-${edge} border-r-${edge} border-[${pressed ? c.light : c.shade}] ${
        pressed ? `bg-[${c.pressed}]` : `bg-[${c.panel}] active:bg-[${c.pressed}]`
      } ${inner}`}
    >
      {children}
    </div>
  </div>
)

// The Deskbar's menu: a cut gem.
const Gem = () => (
  <svg viewBox="0 0 24 20" className={`w-[${px(28)}] h-[${px(23)}]`}>
    <path d="M6 1H18L23 7L12 19L1 7Z" fill="#3a78d8" />
    <path d="M8 1H16L18 7H6Z" fill="#b4d8ff" />
    <path d="M6 1H8L6 7H1Z" fill="#78b2f6" />
    <path d="M16 1H18L23 7H18Z" fill="#2c66c4" />
    <path d="M1 7H6L12 19Z" fill="#2858ab" />
    <path d="M6 7H18L12 19Z" fill="#4f92ea" />
    <path d="M18 7H23L12 19Z" fill="#1c4690" />
    <path d="M6 1H18L23 7L12 19L1 7Z" fill="none" stroke="#0f2a5e" strokeWidth="0.9" strokeLinejoin="round" />
    <path d="M19.5 0.5L20.2 2.3L22 3L20.2 3.7L19.5 5.5L18.8 3.7L17 3L18.8 2.3Z" fill="#ffffff" />
  </svg>
)

// The open scene in the Deskbar: a window of its own, yellow tab and all.
const SceneGlyph = () => (
  <svg viewBox="0 0 16 16" className={`w-[${px(16)}] h-[${px(16)}] shrink-0`}>
    <rect x="0.5" y="0.5" width="9" height="4" fill="#ffcb00" stroke="#000000" />
    <rect x="0.5" y="4.5" width="15" height="11" fill="#d8d8d8" stroke="#000000" />
    <rect x="2.5" y="6.5" width="11" height="7" fill="#336698" stroke="#6c6c6c" />
  </svg>
)

const GEAR = 'M7 0.5H9L9.4 2.6L10.9 3.2L12.6 1.9L14.1 3.4L12.8 5.1L13.4 6.6L15.5 7V9L13.4 9.4L12.8 10.9L14.1 12.6L12.6 14.1L10.9 12.8L9.4 13.4L9 15.5H7L6.6 13.4L5.1 12.8L3.4 14.1L1.9 12.6L3.2 10.9L2.6 9.4L0.5 9V7L2.6 6.6L3.2 5.1L1.9 3.4L3.4 1.9L5.1 3.2L6.6 2.6ZM10.5 8A2.5 2.5 0 1 0 5.5 8A2.5 2.5 0 1 0 10.5 8Z'

const SettingsGlyph = () => (
  <svg viewBox="0 0 16 16" className={`w-[${px(16)}] h-[${px(16)}] shrink-0`}>
    <path d={GEAR} fill="#9a9a9a" stroke="#000000" strokeWidth="0.8" strokeLinejoin="round" />
  </svg>
)

// Four bars for the Wi-Fi signal and the battery, nothing on a frame that cannot tell.
function Signal({ rssi }) {
  if (typeof rssi !== 'number') return null
  const level = rssi >= -55 ? 4 : rssi >= -65 ? 3 : rssi >= -75 ? 2 : 1
  return (
    <div className={`flex items-end gap-[${px(1)}] h-[${px(12)}]`}>
      {[4, 6, 9, 12].map((height, i) => (
        <div className={`w-[${px(3)}] h-[${px(height)}] ${i < level ? 'bg-black' : `bg-[${c.shade}]`}`} />
      ))}
    </div>
  )
}

function Battery({ percent }) {
  if (typeof percent !== 'number') return null
  return (
    <svg viewBox="0 0 10 16" className={`w-[${px(8)}] h-[${px(13)}]`}>
      <rect x="3" y="0" width="4" height="2" fill="#000000" />
      <rect x="0.5" y="1.5" width="9" height="14" fill="#ffffff" stroke="#000000" />
      <rect x="2" y={3 + (11 * (100 - Math.min(100, percent))) / 100} width="6" height={(11 * Math.min(100, percent)) / 100} fill={percent > 15 ? '#30b030' : '#d02020'} />
    </svg>
  )
}

// A running scene in the Deskbar.
const Team = ({ pressed, dim, label, onClick, className = '', children }) => (
  <Bevel pressed={pressed} className={className} inner={`items-center gap-[${px(6)}] px-[${px(6)}] h-[${px(24)}]`} onClick={onClick}>
    {children}
    <span className={`truncate min-w-0 ${dim ? `text-[${c.shade}]` : ''}`}>{label}</span>
  </Bevel>
)

// The tray: sunk into the Deskbar, with the signal, the battery and the clock.
const Tray = ({ app, now, className = '', onClick }) => (
  <Bevel className={className} inner={`items-center p-[${px(3)}]`} onClick={onClick}>
    <div className={`flex flex-1 border-t-${edge} border-l-${edge} border-[${c.shade}]`}>
      <div className={`flex flex-1 items-center gap-[${px(5)}] h-[${px(18)}] px-[${px(5)}] border-b-${edge} border-r-${edge} border-[${c.light}]`}>
        <Signal rssi={app.frame.wifiRssi} />
        <Battery percent={app.frame.batteryPercent} />
        <div className="flex-1" />
        <span className="whitespace-nowrap">{clock(now, on(app.state.twentyFourHour))}</span>
      </div>
    </div>
  </Bevel>
)

// The tab's two boxes, raised a little from the yellow.
const CloseBox = ({ onClick }) => (
  <div className={`flex p-[${px(2)}]`} onClick={onClick}>
    <svg viewBox="0 0 13 13" className={`w-[${px(13)}] h-[${px(13)}]`}>
      <linearGradient id="beBox" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="13" y2="13">
        <stop offset="0" stopColor="#fffbe2" />
        <stop offset="1" stopColor="#f0b400" />
      </linearGradient>
      <rect x="0.5" y="0.5" width="12" height="12" fill="url(#beBox)" stroke={c.tabShade} />
      <path d="M1.5 11V1.5H11" fill="none" stroke="#ffffff" />
    </svg>
  </div>
)

const ZoomBox = ({ onClick }) => (
  <div className={`flex p-[${px(2)}]`} onClick={onClick}>
    <svg viewBox="0 0 13 13" className={`w-[${px(13)}] h-[${px(13)}]`}>
      <linearGradient id="beZoom" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="13" y2="13">
        <stop offset="0" stopColor="#fffbe2" />
        <stop offset="1" stopColor="#f0b400" />
      </linearGradient>
      <rect x="3.5" y="3.5" width="9" height="9" fill="url(#beZoom)" stroke={c.tabShade} />
      <rect x="0.5" y="0.5" width="7" height="7" fill="url(#beZoom)" stroke={c.tabShade} />
      <path d="M1.5 6V1.5H6" fill="none" stroke="#ffffff" />
    </svg>
  </div>
)

// The window: a yellow tab as wide as its title on the top left, then a grey
// frame, lit at the top left and shaded at the bottom right, around the scene.
const Window = ({ title, onClose, onZoom, onHide, children }) => (
  <div className="flex flex-col flex-1 min-w-0 min-h-0">
    <div className={`flex self-start max-w-full border-t-${edge} border-l-${edge} border-r-${edge} border-[${c.line}]`}>
      <div className={`flex flex-1 min-w-0 border-t-${edge} border-l-${edge} border-[${c.tabLight}]`}>
        <div
          className={`flex flex-1 min-w-0 items-center h-[${px(22)}] gap-[${px(4)}] pl-[${px(2)}] pr-[${px(2)}] border-r-${edge} border-[${c.tabShade}] bg-[${c.tab}]`}
          onDoubleClick={onHide}
        >
          <CloseBox onClick={onClose} />
          <span className={`font-bold truncate min-w-0 px-[${px(4)}]`}>{title}</span>
          <ZoomBox onClick={onZoom} />
        </div>
      </div>
    </div>
    <div className={`flex flex-col flex-1 min-h-0 border-[${edge}px] border-[${c.line}]`}>
      <div className={`flex flex-col flex-1 min-h-0 border-t-${edge} border-l-${edge} border-[${c.light}]`}>
        <div className={`flex flex-col flex-1 min-h-0 p-[${px(3)}] border-b-${edge} border-r-${edge} border-[${c.shade}] bg-[${c.panel}]`}>
          <div className={`flex flex-col flex-1 min-h-0 border-t-${edge} border-l-${edge} border-[${c.shade}]`}>
            <div className={`flex flex-col flex-1 min-h-0 border-b-${edge} border-r-${edge} border-[${c.light}]`}>{children}</div>
          </div>
        </div>
      </div>
    </div>
  </div>
)

// Tracker's icons, drawn from above and to the side as they were.
const DiskIcon = () => (
  <svg viewBox="2 4 28 24" className={`w-[${px(42)}] h-[${px(36)}]`}>
    <path d="M3 13L16 7L29 13L16 19Z" fill="#ececec" />
    <path d="M3 13L16 19V26L3 20Z" fill="#b4b4b4" />
    <path d="M16 19L29 13V20L16 26Z" fill="#8c8c8c" />
    <path d="M5.5 18.2L13.5 22" stroke="#5a5a5a" strokeWidth="1.2" />
    <path d="M21 19.2L25 17.3" stroke="#2ee05a" strokeWidth="1.6" />
    <path d="M3 13L16 7L29 13V20L16 26L3 20ZM3 13L16 19L29 13M16 19V26" fill="none" stroke="#202020" strokeWidth="0.9" strokeLinejoin="round" />
  </svg>
)

const FolderIcon = ({ children }) => (
  <svg viewBox="2 4 28 24" className={`w-[${px(42)}] h-[${px(36)}]`}>
    <path d="M3 15L9 12L12 13.4L17 11L29 17L15 24Z" fill="#f6d36a" />
    <path d="M3 15L15 24V27L3 18Z" fill="#d9a22a" />
    <path d="M15 24L29 17V20L15 27Z" fill="#b8841a" />
    <path d="M3 15L9 12L12 13.4L17 11L29 17V20L15 27L3 18ZM3 15L15 24L29 17M15 24V27" fill="none" stroke="#3a2a08" strokeWidth="0.9" strokeLinejoin="round" />
    {children}
  </svg>
)

const DesktopIcon = ({ label, onClick, children }) => (
  <div className={`flex flex-col items-center gap-[${px(2)}] w-[${px(88)}] py-[${px(4)}] active:bg-black/25`} onClick={onClick}>
    {children}
    <span className={`text-white text-[${px(13)}] whitespace-nowrap px-[${px(2)}]`}>{label}</span>
  </div>
)

export function get(app) {
  // app.frame's size is the panel's over the render scale, before the frame's rotation.
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = turned ? app.frame.height : app.frame.width
  const shortSide = Math.min(app.frame.width, app.frame.height) * (app.frame.scale || 1)
  zoom = shortSide >= 1000 ? 2 : shortSide >= 480 ? 1 : shortSide / 480
  edge = Math.max(1, Math.round(zoom))
  c = app.frame.color === false ? MONO : app.frame.paper ? PAPER : R5
  // The Deskbar stands in the corner where there is room beside the window, and
  // runs along the top where there is not; the icons need the corner's column.
  const corner = width >= 600 * Math.max(zoom, 1)
  const now = new Date()
  // The clock changes on the minute: nothing to draw until then.
  frameos.setNextSleep(60 - now.getSeconds())
  const name = app.frame.sceneName || 'FrameOS'
  const builtIn = app.frame.systemScene === true
  const settingsOpen = builtIn && name.includes('settings')
  const listOpen = builtIn && !settingsOpen
  // The scene a built-in one opened over keeps its place in the Deskbar.
  const scene = builtIn ? app.state.openedOver || '' : name
  const title = listOpen ? 'Scenes' : settingsOpen ? (name.startsWith('Frame') ? 'Preferences' : 'Settings') : name
  const hidden = !builtIn && app.state.hidden === true
  const zoomed = app.state.zoomed === true
  const framed = on(app.state.showWindow)
  // A built-in scene's own command, again, goes back to the scene it opened over.
  const closeBuiltIn = () => frameos.dispatch(settingsOpen ? 'sceneSettings' : 'sceneSwitcher')
  const openList = () => frameos.dispatch('sceneSwitcher', { swap: true })
  const openSettings = () => frameos.dispatch('sceneSettings')
  const openFrame = () => frameos.dispatch('sceneSettings', { page: 'frame' })
  const showScene = builtIn ? closeBuiltIn : () => frameos.setState('hidden', !hidden)
  const content = hidden ? (
    <div className="flex-1" />
  ) : framed ? (
    <div className={`flex flex-col flex-1 min-w-0 min-h-0 ${zoomed ? '' : `p-[${px(12)}]`}`}>
      <Window
        title={title}
        onClose={builtIn ? closeBuiltIn : () => frameos.dispatch('sceneSwitcher')}
        onZoom={() => frameos.setState('zoomed', !zoomed)}
        onHide={builtIn ? closeBuiltIn : () => frameos.setState('hidden', true)}
      >
        <yield />
      </Window>
    </div>
  ) : (
    <yield />
  )
  const sceneTeam = scene ? (
    <Team pressed={false} dim={hidden} label={scene} onClick={showScene} className={corner ? '' : 'min-w-0 shrink'}>
      <SceneGlyph />
    </Team>
  ) : null
  const settingsTeam = (
    <Team pressed={settingsOpen} label="Settings" onClick={openSettings} className="shrink-0">
      <SettingsGlyph />
    </Team>
  )
  if (!corner) {
    return (
      <div className={`flex flex-col w-full h-full ${c.desk} text-black text-[${px(13)}]`}>
        <div className={`flex items-stretch shrink-0 border-b-${edge} border-[${c.line}]`}>
          <Bevel pressed={listOpen} className="shrink-0" inner={`items-center justify-center w-[${px(46)}] h-[${px(28)}]`} onClick={openList}>
            <Gem />
          </Bevel>
          {sceneTeam}
          {settingsTeam}
          <div className={`flex-1 bg-[${c.panel}]`} />
          <Tray app={app} now={now} className="shrink-0" onClick={openFrame} />
        </div>
        {content}
      </div>
    )
  }
  return (
    <div className={`flex w-full h-full ${c.desk} text-black text-[${px(13)}]`}>
      {content}
      <div className={`flex flex-col items-center shrink-0 w-[${px(156)}]`}>
        <div className={`flex flex-col self-stretch border-l-${edge} border-b-${edge} border-[${c.line}]`}>
          <Bevel pressed={listOpen} inner={`items-center justify-center h-[${px(32)}]`} onClick={openList}>
            <Gem />
          </Bevel>
          <Tray app={app} now={now} onClick={openFrame} />
          {sceneTeam}
          {settingsTeam}
        </div>
        {on(app.state.showIcons) ? (
          <div className={`flex flex-col items-center gap-[${px(8)}] pt-[${px(14)}]`}>
            <DesktopIcon label="Frame" onClick={openFrame}>
              <DiskIcon />
            </DesktopIcon>
            <DesktopIcon label="Scenes" onClick={openList}>
              <FolderIcon />
            </DesktopIcon>
            <DesktopIcon label="Settings" onClick={openSettings}>
              <FolderIcon>
                <path d={GEAR} fill="#a8a8a8" stroke="#202020" strokeWidth="0.8" transform="translate(9.5 3.5) scale(0.8)" />
              </FolderIcon>
            </DesktopIcon>
          </div>
        ) : null}
      </div>
    </div>
  )
}
